"""Tiny inventory + prep-waste tracker for small restaurants."""
import csv, sys, datetime

FILE = "log.csv"

def log(item, qty, kind):
    with open(FILE, "a", newline="") as f:
        csv.writer(f).writerow([datetime.date.today().isoformat(), item, qty, kind])

def report():
    waste = {}
    try:
        for date, item, qty, kind in csv.reader(open(FILE)):
            if kind == "waste":
                waste[item] = waste.get(item, 0) + float(qty)
    except FileNotFoundError:
        pass
    for item, q in sorted(waste.items(), key=lambda x: -x[1]):
        print(f"{item}: {q} wasted")

if __name__ == "__main__":
    if sys.argv[1] == "log":
        log(sys.argv[2], sys.argv[3], sys.argv[4])
    elif sys.argv[1] == "report":
        report()
